uniform float amzp_dissolveAmt;
uniform float amzp_dissolveSpeed;
uniform float amzp_dissolveCurve;
uniform float amzp_amplitude;
uniform float amzp_frequency;
uniform float amzp_seed;
uniform float amzp_smoothness;
